az automation account create \
  --name my-automation \
  --resource-group my-rg \
  --location eastus

# PowerShell runbook (stop idle VMs)
param([Parameter(Mandatory=$true)][int]$IdleThresholdMinutes)

$vms = Get-AzVM -Status | Where-Object {
  $_.PowerState -eq 'VM running' -and
  (Get-AzMetric -ResourceId $_.Id -MetricName 'Percentage CPU' -TimeGrain 00:05:00 -WarningAction SilentlyContinue |
    Measure-Object -Property Average -Average).Average -lt 5
}
foreach ($vm in $vms) {
  Stop-AzVM -ResourceGroupName $vm.ResourceGroupName -Name $vm.Name -Force
  Write-Output "Stopped: $($vm.Name)"
}

