# Logic App definition (simplified ARM/Bicep)
resource logicApp 'Microsoft.Logic/workflows@2019-05-01' = {
  name: 'my-logic-app'
  location: resourceGroup().location
  properties: {
    state: 'Enabled'
    definition: {
      '$schema': 'https://schema.management.azure.com/providers/Microsoft.Logic/schemas/2016-06-01/workflowdefinition.json#'
      contentVersion: '1.0.0.0'
      triggers: {
        WhenABlobIsAdded: {
          type: 'ApiConnection'
          inputs: {
            host: {
              connection: {
                name: '@parameters("$connections")["azureblob"]["connectionId"]'
              }
            }
            method: 'get'
            path: '/v2/datasets/@{encodeURIComponent(encodeURIComponent("AccountNameFromSettings"))}/triggers/onnewfile'
            queries: {
              folderId: 'data'
            }
          }
          recurrence: {
            frequency: 'Minute'
            interval: 5
          }
        }
      }
      actions: {
        ProcessFile: {
          type: 'ApiConnection'
          inputs: {
            host: { connection: { name: '@parameters("$connections")["azureblob"]["connectionId"]' } }
            method: 'get'
            path: '/v2/datasets/@{encodeURIComponent(encodeURIComponent("AccountNameFromSettings"))}/files/@{encodeURIComponent(encodeURIComponent(triggerOutputs()?.headers?["x-ms-file-name"]))}/content'
          }
          runAfter: {}
        },
        SendApprovalEmail: {
          type: 'ApiConnection'
          inputs: {
            host: { connection: { name: '@parameters("$connections")["office365"]["connectionId"]' } }
            method: 'post'
            path: '/mail'
            body: {
              to: 'approver@company.com'
              subject: 'Approve file: @{triggerOutputs()?.headers?["x-ms-file-name"]}'
              body: 'A new file was uploaded. Please review.'
            }
          }
          runAfter: { ProcessFile: ['Succeeded'] }
        }
      }
      outputs: {}
    }
    parameters: {
      '$connections': {
        value: {
          azureblob: { connectionId: '/subscriptions/.../connections/azureblob', connectionName: 'azureblob', id: '/subscriptions/...' }
          office365: { connectionId: '/subscriptions/.../connections/office365', connectionName: 'office365', id: '/subscriptions/...' }
        }
      }
    }
  }
}
